package com.curso.repositories;
import java.sql.*;import liquibase.*;import liquibase.database.*;import liquibase.database.jvm.JdbcConnection;import liquibase.resource.ClassLoaderResourceAccessor;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class MigracaoCorretoraPostgresTest{@Test void upgradeRealPreservaLegadoESequencia()throws Exception{String url=System.getProperty("test.postgres.url");Assumptions.assumeTrue(url!=null&&!url.isBlank());aplicar(url,"db/changelog/changes/001-criar-estrutura-inicial.xml");aplicar(url,"db/changelog/changes/002-criar-estrutura-investimentos.xml");aplicar(url,"db/changelog/changes/003-serializar-criacao-ativos.xml");try(Connection c=conectar(url);Statement s=c.createStatement()){s.executeUpdate("insert into usuario(id,nome,email,cpf,senha_hash) values(7,'Legado','legado@test.com','77777777777','h')");s.executeUpdate("insert into ativo(id,simbolo,nome,bolsa) values(8,'PETR4','Petrobras','B3')");s.executeUpdate("insert into transacao(id,usuario_id,ativo_id,tipo,quantidade,valor_unitario,data_operacao) values(9,7,8,'COMPRA',10,20,TIMESTAMP '2026-09-01 10:00:00')");}aplicar(url,"db/changelog/changes/004-adicionar-corretoras.xml");try(Connection c=conectar(url);Statement s=c.createStatement();ResultSet r=s.executeQuery("select t.id,t.quantidade,t.valor_unitario,t.data_operacao,c.codigo from transacao t join corretora c on c.id=t.corretora_id where t.id=9")){assertTrue(r.next());assertEquals(9,r.getLong("id"));assertEquals(0,new java.math.BigDecimal("10").compareTo(r.getBigDecimal("quantidade")));assertEquals(0,new java.math.BigDecimal("20").compareTo(r.getBigDecimal("valor_unitario")));assertEquals("NAO_INFORMADA",r.getString("codigo"));assertEquals(Timestamp.valueOf("2026-09-01 10:00:00"),r.getTimestamp("data_operacao"));}try(Connection c=conectar(url);Statement s=c.createStatement();ResultSet r=s.executeQuery("select nextval('seq_corretora')")){assertTrue(r.next());assertTrue(r.getLong(1)>=10);}}
 private Connection conectar(String url)throws SQLException{return DriverManager.getConnection(url,"postgres","teste-descartavel");}private void aplicar(String url,String arquivo)throws Exception{Connection c=conectar(url);Database db=DatabaseFactory.getInstance().findCorrectDatabaseImplementation(new JdbcConnection(c));try(Liquibase l=new Liquibase(arquivo,new ClassLoaderResourceAccessor(),db)){l.update(new Contexts(),new LabelExpression());}}
}
